package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.HydroacousticNetwork;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;public class HydroacousticExciterBlock extends Block{public static final IntegerProperty FREQUENCY=IntegerProperty.create("frequency",1,15);public HydroacousticExciterBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(FREQUENCY,8));}@Override public MapCodec<HydroacousticExciterBlock> codec(){return RedstoneEngineering.HYDROACOUSTIC_EXCITER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FREQUENCY);}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos q,boolean m){if(l instanceof ServerLevel sl){int a=l.getBestNeighborSignal(p);if(a>0)HydroacousticNetwork.propagate(sl,p,a,s.getValue(FREQUENCY));}}}